Ltac Zify.zify_convert_to_euclidean_division_equations_flag ::= constr:(true).
#[global] Unset Lia Cache. #[global] Unset Nia Cache. #[global] Unset Nra Cache.

Lemma zero_chunk_at : forall m TB sz off n,
  (forall z, TB <= z < TB + sz -> m (wa z) = Some (b8 0)) -> stk asegs m TB (TB + sz) ->
  0 <= off -> off + Z.of_nat n <= sz ->
  rw_cells asegs m (TB + off) [CB n (repeat (b8 0) n)].
Proof.
